function convText(snapObj) {
  var out = [];
  var keys = Object.keys(snapObj.refs);
  for (var k of keys) {
    var e = snapObj.refs[k];
    if (e && (e.role === 'static' || e.role === 'StaticText' || e.role === 'text')) {
      if (e.name && e.name.trim()) out.push(e.name.trim());
    }
  }
  return out;
}
